"""Генерирует два дополнительных тестовых .docx (вариации ДИ) для пакетной проверки."""
from pathlib import Path

from docx import Document

OUT = Path(__file__).resolve().parent


def make_accountant() -> None:
    doc = Document()
    doc.add_heading("ДОЛЖНОСТНАЯ ИНСТРУКЦИЯ", level=1)
    doc.add_paragraph("Главный бухгалтер")
    doc.add_paragraph("УТВЕРЖДАЮ")
    doc.add_paragraph("Генеральный директор ООО «Пример» __________ /Иванов И.И./")
    doc.add_paragraph("«10» февраля 2026 г.")

    doc.add_heading("1. Общие положения", level=2)
    doc.add_paragraph(
        "1.1. Главный бухгалтер относится к категории руководителей и подчиняется "
        "непосредственно генеральному директору."
    )
    doc.add_paragraph(
        "1.2. На должность назначается лицо, имеющее высшее экономическое образование "
        "и стаж работы по специальности не менее 5 лет."
    )
    doc.add_paragraph(
        "1.3. В своей деятельности руководствуется законодательством РФ о бухгалтерском "
        "учёте, налоговым законодательством и настоящей инструкцией."
    )

    doc.add_heading("2. Должностные обязанности", level=2)
    doc.add_paragraph(
        "2.1. Ведёт бухгалтерский и налоговый учёт по государственному контракту "
        "№ 177-ГК от 01.02.2026."
    )
    doc.add_paragraph("2.2. Формирует и сдаёт бухгалтерскую и налоговую отчётность.")
    doc.add_paragraph("2.3. Контролирует расходование средств контракта.")

    doc.add_heading("3. Права", level=2)
    doc.add_paragraph(
        "3.1. Требовать от подразделений документы, необходимые для ведения учёта."
    )

    doc.add_heading("4. Ответственность", level=2)
    doc.add_paragraph(
        "4.1. Несёт ответственность в пределах, установленных законодательством РФ."
    )
    doc.save(OUT / "sample_di_buhgalter.docx")


def make_manager() -> None:
    doc = Document()
    doc.add_heading("ДОЛЖНОСТНАЯ ИНСТРУКЦИЯ", level=1)
    doc.add_paragraph("Менеджер по закупкам")
    doc.add_paragraph("УТВЕРЖДАЮ")
    doc.add_paragraph("Директор ООО «Пример» __________ /Сидоров С.С./")
    doc.add_paragraph("«05» марта 2026 г.")

    doc.add_heading("1. Общие положения", level=2)
    doc.add_paragraph(
        "1.1. Менеджер по закупкам относится к категории специалистов, подчиняется "
        "руководителю отдела закупок."
    )
    doc.add_paragraph(
        "1.2. Назначается лицо со средним профессиональным образованием и стажем "
        "не менее 1 года."
    )

    doc.add_heading("2. Должностные обязанности", level=2)
    doc.add_paragraph(
        "2.1. Осуществляет закупку товаров и услуг для исполнения государственных "
        "контрактов в соответствии с 44-ФЗ."
    )
    doc.add_paragraph("2.2. Взаимодействует с поставщиками, проверяет контрагентов.")
    doc.add_paragraph("2.3. Ведёт реестр закупок и отчётность по контрактам.")

    doc.add_heading("3. Права", level=2)
    doc.add_paragraph(
        "3.1. Запрашивать коммерческие предложения и документы у поставщиков."
    )

    doc.add_heading("4. Ответственность", level=2)
    doc.add_paragraph(
        "4.1. Несёт материальную и дисциплинарную ответственность по законодательству РФ."
    )
    doc.save(OUT / "sample_di_menedzher.docx")


if __name__ == "__main__":
    make_accountant()
    make_manager()
    print("saved")
